"""Validate only PDFs generated by the isolated presentation browser suite."""
import json
import sys
from pathlib import Path

import pypdfium2 as pdfium
from pypdf import PdfReader

folder = Path(sys.argv[1]).resolve()
files = sorted(folder.glob("Apresenta*_TheView-pt-*.pdf"))
assert len(files) == 8, f"Expected 8 generated PDFs, got {len(files)}"
pages_checked = 0
for file in files:
    expected_pages = 2 if "Apt21-22_" in file.name else 1
    with_price = "-com-preco.pdf" in file.name
    reader = PdfReader(file)
    assert len(reader.pages) == expected_pages, (file.name, len(reader.pages))
    assert reader.metadata.title == "Apresentação_Apt" + (
        "21-22" if expected_pages == 2 else "21"
    ) + "_TheView"
    rendered = pdfium.PdfDocument(str(file))
    for index, page in enumerate(reader.pages):
        text = page.extract_text()
        assert "Documento meramente informativo" in text
        assert ("€" in text) == with_price
        assert "NaN" not in text and "undefined" not in text
        assert len(page.images) > 0, "Floor plan must remain embedded"
        assert abs(float(page.mediabox.width) - 595.28) < 2
        assert abs(float(page.mediabox.height) - 841.89) < 2
        image = rendered[index].render(scale=1).to_pil()
        assert image.convert("L").getextrema()[0] < 128, "Blank rendered page"
        image.save(folder / f"{file.stem}-page-{index + 1}.png")
        pages_checked += 1
    rendered.close()
print(json.dumps({"pdfs": len(files), "pages": pages_checked,
                  "a4_portrait": True, "titles": True, "prices": True,
                  "embedded_plans": True, "rendered": True}))
